-- D&D 3.0 Psionics Handbook feat prerequisites from Table 3-1.
WITH desired(slug,explanation) AS (VALUES
('ph3e-psionic-dodge','Dex 13+, Dodge, reserve power points 5+'),('ph3e-inertial-armor','Reserve power points 1+'),('ph3e-talented','Inner Strength'),('ph3e-body-fuel','Inner Strength, Talented'),('ph3e-trigger-power','Inner Strength, Talented, reserve power points n+'),('ph3e-mental-adversary','Cha 13+'),('ph3e-disarm-mind','Cha 13+, Mental Adversary'),('ph3e-mental-leap','Str 13+, Jump 6 ranks, reserve power points 3+'),('ph3e-metacreative','Any item creation feat'),('ph3e-psionic-shot','Dex 13+, Point Blank Shot'),('ph3e-fell-shot','Dex 13+, Point Blank Shot, Psionic Shot, base attack bonus +3'),('ph3e-return-shot','Dex 13+, Point Blank Shot, Psionic Shot, reserve power points 5+'),('ph3e-great-sunder','Str 13+, Power Attack, Sunder, reserve power points 5+'),('ph3e-psionic-weapon','Str 13+, Power Attack'),('ph3e-deep-impact','Str 13+, Power Attack, Psionic Weapon, reserve power points 3+'),('ph3e-greater-power-penetration','Power Penetration'),('ph3e-psionic-fist','Str 13+'),('ph3e-power-touch','Str 13+, Psionic Fist'),('ph3e-unavoidable-strike','Str 13+, Psionic Fist, base attack bonus +3'),('ph3e-greater-psionic-focus','Psionic Focus'),('ph3e-mind-trap','Psychic Bastion'),('ph3e-psychoanalyst','Cha 13+'),('ph3e-psychic-inquisitor','Cha 13+, Psychoanalyst'),('ph3e-rapid-metabolism','Con 13+'),('ph3e-psionic-metabolism','Con 13+, Rapid Metabolism'),('ph3e-speed-of-thought','Wis 13+, reserve power points 1+'),('ph3e-psionic-charge','Wis 13+, Speed of Thought, reserve power points 3+'),('ph3e-up-the-walls','Wis 13+, Speed of Thought, Psionic Charge, reserve power points 5+'),('ph3e-stand-still','Str 13+, reserve power points 1+'),('ph3e-craft-crystal-capacitor','Manifester level 9th+'),('ph3e-craft-dorje','Manifester level 5th+'),('ph3e-craft-psionic-arms-and-armor','Manifester level 5th+'),('ph3e-craft-universal-item','Manifester level 3rd+'),('ph3e-encode-stone','Manifester level 1st+'),('ph3e-scribe-tattoo','Manifester level 3rd+'),('ph3e-persistent-power','Extend Power'))
INSERT INTO dnd35_feat_prerequisites(feat_id,expression,explanation)
SELECT f.id,json_object('version',1,'condition',json_object('kind','custom','description',d.explanation,'extension',json_object('key','dnd35.prerequisite.source-text','version',1,'parameters',json_object('text',d.explanation)))),d.explanation
FROM desired d JOIN dnd35_feats f ON f.slug=d.slug AND f.owner_user_id IS NULL
ON CONFLICT(feat_id) DO UPDATE SET expression=excluded.expression,explanation=excluded.explanation;
